script:
document.querySelectorAll("[data-lns],[data-hang],#kolam,#star").forEach(el=>el.replaceChildren());

const $ = id => document.getElementById(id);
const WA = FMI.content.whatsapp || "";           /* the couple's WhatsApp in a real invitation */
const TARGET = new Date(FMI.content.date+"T"+FMI.content.time+":00+05:30").getTime();
const calm = FMI.reduceMotion || matchMedia("(prefers-reduced-motion: reduce)").matches;
const params = new URLSearchParams(FMI.search);
const preview = false;

/* guest name from ?to=Kumar-Family */
let guest = "";
try {
  guest = (params.get("to") || "").replace(/[-_+]+/g, " ").replace(/\s+/g, " ").trim().slice(0, 40);
  guest = guest.split(" ").map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(" ");
} catch (e) {}
if (guest) {
  $("dear").textContent = "Dear " + guest + ",";
  $("dear").hidden = false;
  $("r-name").value = guest;
  $("l-name").value = guest;
  document.title = "Dear " + guest + " · Karthik & Nila's wedding";
}

/* lanterns: a seeded scatter so every visit looks the same */
let seed = 7;
const rnd = () => { seed = (seed * 16807) % 2147483647; return (seed - 1) / 2147483646; };
const LN = {
  far:   { n: 16, s: [3, 6],  d: [44, 64], g: false },
  mid:   { n: 10, s: [7, 12], d: [28, 40], g: true },
  near:  { n: 5,  s: [15, 23], d: [17, 24], g: true },
  room:  { n: 6,  s: [5, 8],  d: [22, 34], g: true },
  night: { n: 12, s: [3, 7],  d: [40, 60], g: false }
};
document.querySelectorAll("[data-lns]").forEach(box => {
  const c = LN[box.dataset.lns]; if (!c) return;
  if (calm) box.classList.add("calm-ln");
  for (let i = 0; i < c.n; i++) {
    const el = document.createElement("i"); el.className = "ln" + (c.g ? " g" : "");
    const d = c.d[0] + rnd() * (c.d[1] - c.d[0]);
    el.style.setProperty("--x", (2 + rnd() * 90).toFixed(1) + "%");
    el.style.setProperty("--s", (c.s[0] + rnd() * (c.s[1] - c.s[0])).toFixed(2) + "%");
    el.style.setProperty("--d", d.toFixed(1) + "s");
    el.style.setProperty("--dl", (-rnd() * d).toFixed(1) + "s");
    el.style.setProperty("--sw", (3.5 + rnd() * 3).toFixed(1) + "s");
    el.style.setProperty("--cy", (6 + rnd() * 80).toFixed(1) + "%");
    el.innerHTML = '<img src="/assets/flagship/hindu/l' + (1 + Math.floor(rnd() * 12)) + '.webp" alt="">';
    box.appendChild(el);
  }
});
function sizeTallLanterns(){
  document.querySelectorAll('[data-lns="night"],[data-lns="room"]').forEach(b => b.style.setProperty("--dist", -(b.offsetHeight + 160) + "px"));
}
sizeTallLanterns();

/* stars for the night section */
function starfield(el, n, a){
  const sec = $("night"); const w = sec.offsetWidth, h = sec.offsetHeight; const out = [];
  for (let i = 0; i < n; i++) out.push(Math.round(rnd() * w) + "px " + Math.round(rnd() * h * .7) + "px 0 " + (rnd() < .2 ? "1px" : "0") + " rgba(255,248,230," + (a * (.4 + rnd() * .6)).toFixed(2) + ")");
  el.style.boxShadow = out.join(",");
}
starfield($("stars"), 90, .9); starfield($("stars2"), 40, 1);

/* kolam: a lotus kolam drawn as one set of white lines around the dots */
const K = (() => {
  const ns = "http://www.w3.org/2000/svg";
  const svg = document.createElementNS(ns, "svg"); svg.setAttribute("viewBox", "-112 -112 224 224");
  const P = (r, a) => [r * Math.cos(a), r * Math.sin(a)];
  const f = v => v.toFixed(2);
  const rot = (x, y, a) => [x * Math.cos(a) - y * Math.sin(a), x * Math.sin(a) + y * Math.cos(a)];
  const paths = [];
  function add(d, a, b){ const p = document.createElementNS(ns, "path"); p.setAttribute("d", d); svg.appendChild(p); paths.push({ el: p, a, b }); }
  function dot(r, a){ const c = document.createElementNS(ns, "circle"); const [x, y] = P(r, a); c.setAttribute("cx", f(x)); c.setAttribute("cy", f(y)); c.setAttribute("r", "1.9"); svg.appendChild(c); }
  /* dots */
  dot(0, 0);
  for (let i = 0; i < 8; i++) dot(36, (i + .5) * Math.PI / 4);
  for (let i = 0; i < 16; i++) dot(58, i * Math.PI / 8);
  for (let i = 0; i < 8; i++) dot(88, i * Math.PI / 4);
  /* 1 · eight-petal centre */
  let d = "";
  for (let i = 0; i < 8; i++) {
    const a = i * Math.PI / 4;
    const q = (x, y) => rot(x, y, a).map(f).join(" ");
    d += "M0 0 C" + q(14, -16) + " " + q(34, -12) + " " + q(43, 0) + " C" + q(34, 12) + " " + q(14, 16) + " 0 0 ";
  }
  add(d, .05, .24);
  /* 2 · loops out around the sixteen dots, joined by an inner circle */
  d = ""; const R = 46, ang = Math.PI / 8, w = .2;
  for (let i = 0; i < 16; i++) {
    const a = i * ang;
    const [sx, sy] = P(R, a - w), [ex, ey] = P(R, a + w);
    const [c1x, c1y] = P(R + 26, a - w * 1.9), [c2x, c2y] = P(R + 26, a + w * 1.9);
    const [nx, ny] = P(R, a + ang - w);
    d += (i ? "" : "M" + f(sx) + " " + f(sy)) + " C" + f(c1x) + " " + f(c1y) + " " + f(c2x) + " " + f(c2y) + " " + f(ex) + " " + f(ey) + " A" + R + " " + R + " 0 0 1 " + f(nx) + " " + f(ny);
  }
  add(d + " Z", .26, .24);
  /* 3 · eight almond petals between the outer dots */
  d = "";
  for (let i = 0; i < 8; i++) {
    const a = (i + .5) * Math.PI / 4;
    const q = (x, y) => rot(x, y, a).map(f).join(" ");
    d += "M" + q(70, 0) + " C" + q(80, -14) + " " + q(98, -12) + " " + q(108, 0) + " C" + q(98, 12) + " " + q(80, 14) + " " + q(70, 0) + " ";
  }
  add(d, .46, .2);
  /* 4 · rings around the outer dots */
  d = "";
  for (let i = 0; i < 8; i++) {
    const [x, y] = P(88, i * Math.PI / 4);
    d += "M" + f(x + 7) + " " + f(y) + " A7 7 0 1 1 " + f(x - 7) + " " + f(y) + " A7 7 0 1 1 " + f(x + 7) + " " + f(y) + " ";
  }
  add(d, .6, .14);
  /* 5 · scalloped border */
  d = ""; const n = 32, RB = 108;
  for (let i = 0; i <= n; i++) {
    const [x, y] = P(RB, i * 2 * Math.PI / n);
    if (!i) { d += "M" + f(x) + " " + f(y); continue; }
    d += " A" + f(RB * Math.PI / n * 1.05) + " " + f(RB * Math.PI / n * 1.05) + " 0 0 1 " + f(x) + " " + f(y);
  }
  add(d, .68, .2);
  $("kolam").appendChild(svg);
  paths.forEach(p => { p.L = p.el.getTotalLength(); p.el.style.strokeDasharray = p.L; p.el.style.strokeDashoffset = calm ? 0 : p.L; });
  return paths;
})();

/* scroll engine: each scene gets --p from 0 to 1 */
const scenes = [...document.querySelectorAll("[data-scene]")];
const root = document.documentElement, kolamScene = $("s-kolam"), lotus = $("lotus");
let ticking = false;
function update(){
  const vh = innerHeight;
  for (const s of scenes) {
    const r = s.getBoundingClientRect();
    const pinned = s.classList.contains("scene") && !calm;
    let p = pinned ? -r.top / Math.max(1, r.height - vh) : (vh - r.top) / (vh + r.height);
    p = Math.min(1, Math.max(0, p));
    s.style.setProperty("--p", p.toFixed(4));
    if (s === kolamScene && !calm) K.forEach(k => { const t = Math.min(1, Math.max(0, (p - k.a) / k.b)); k.el.style.strokeDashoffset = (k.L * (1 - t)).toFixed(1); });
  }
  if (!calm) {
    const lr = lotus.getBoundingClientRect();
    const o = Math.min(1, Math.max(0, (vh * .92 - lr.top) / (vh * .5)));
    lotus.style.setProperty("--o", o.toFixed(3));
  } else lotus.style.setProperty("--o", 1);
  const max = document.documentElement.scrollHeight - vh;
  root.style.setProperty("--gp", max > 0 ? (scrollY / max).toFixed(4) : 0);
  ticking = false;
}
addEventListener("scroll", () => { if (!ticking) { ticking = true; requestAnimationFrame(update); } }, { passive: true });
addEventListener("resize", () => { sizeTallLanterns(); update(); });
update();
if (calm) scenes.forEach(s => s.style.setProperty("--p", 1));

/* reveal on view */
const io = "IntersectionObserver" in window ? new IntersectionObserver(es => es.forEach(e => {
  if (e.isIntersecting) { e.target.classList.add("in"); io.unobserve(e.target); }
}), { threshold: .15 }) : null;
document.querySelectorAll(".rv").forEach(el => io ? io.observe(el) : el.classList.add("in"));

/* music: starts with the first lantern, toggled from the corner button */
const music = $("music"), mBtn = $("music-btn");
let musicWanted = false;
function paintMusic(){ mBtn.classList.toggle("on", musicWanted); mBtn.setAttribute("aria-pressed", musicWanted); mBtn.setAttribute("aria-label", musicWanted ? "Pause music" : "Play music"); }
function setMusic(on){
  musicWanted = on;
  if (on) { music.volume = .75; const p = music.play(); if (p) p.catch(() => { musicWanted = false; paintMusic(); }); }
  else music.pause();
  paintMusic();
}
mBtn.addEventListener("click", () => setMusic(!musicWanted));
document.addEventListener("visibilitychange", () => { if (document.hidden) music.pause(); else if (musicWanted) music.play().catch(() => {}); });

/* gate */
const gate = $("gate");
function openGate(withSound){
  gate.classList.add("lit");
  document.body.classList.remove("locked");
  mBtn.hidden = false;
  if (withSound) setMusic(true); else paintMusic();
  setTimeout(() => { gate.hidden = true; }, calm ? 300 : 1900);
}
$("open").addEventListener("click", () => openGate(true));
if (preview) { gate.hidden = true; document.body.classList.remove("locked"); }

/* countdown */
const cells = {}; document.querySelectorAll("#count b").forEach(b => cells[b.dataset.u] = b);
function tick(){
  let s = Math.floor((TARGET - Date.now()) / 1000);
  if (s <= 0) { $("count").innerHTML = '<p style="grid-column:1/-1;font-size:1.4rem;font-style:italic">Karthik and Nila are married. Thank you for your blessings!</p>'; return; }
  const d = Math.floor(s / 86400); s -= d * 86400;
  const h = Math.floor(s / 3600); s -= h * 3600;
  const m = Math.floor(s / 60); s -= m * 60;
  cells.d.textContent = d;
  cells.h.textContent = String(h).padStart(2, "0");
  cells.m.textContent = String(m).padStart(2, "0");
  cells.s.textContent = String(s).padStart(2, "0");
}
tick(); setInterval(tick, 1000);

/* light a lantern: it rises from the button and settles among the stars */
let actx, lit = 0;
function chime(){
  try {
    actx = actx || new (window.AudioContext || window.webkitAudioContext)();
    if (actx.state === "suspended") actx.resume();
    const t0 = actx.currentTime + .02, out = actx.createGain(); out.gain.value = .12; out.connect(actx.destination);
    [[1, 1, 2.6], [2, .4, 1.8], [3, .18, 1.2], [4.2, .08, .8]].forEach(([r, g, d]) => {
      const o = actx.createOscillator(); o.type = "sine"; o.frequency.value = 784 * r;
      const v = actx.createGain(); v.gain.setValueAtTime(0, t0); v.gain.linearRampToValueAtTime(g, t0 + .01); v.gain.exponentialRampToValueAtTime(.0001, t0 + d);
      o.connect(v); v.connect(out); o.start(t0); o.stop(t0 + d + .05);
    });
  } catch (e) {}
}
const launch = $("launch"), night = $("night");
$("light-form").addEventListener("submit", e => {
  e.preventDefault();
  const name = $("l-name").value.trim();
  lit++;
  $("lit-msg").textContent = (name ? name + ", your" : "Your") + " lantern is on its way to Karthik & Nila" + (lit > 1 ? " (" + lit + " lit)" : "") + ".";
  chime();
  const btn = e.submitter || $("light-form").querySelector("button");
  const nr = night.getBoundingClientRect(), br = btn.getBoundingClientRect();
  const x0 = br.left + br.width / 2 - nr.left - 32, y0 = br.top - nr.top - 90;
  const el = document.createElement("div"); el.className = "fly";
  el.innerHTML = '<img src="/assets/flagship/hindu/l' + (1 + Math.floor(Math.random() * 12)) + '.webp" alt="">' + (name ? "<span></span>" : "");
  if (name) el.querySelector("span").textContent = "from " + name;
  launch.appendChild(el);
  const vh = innerHeight, topVisible = Math.max(30, -nr.top + 60);
  const tx = (Math.random() - .5) * nr.width * .55, ty = Math.max(topVisible + Math.random() * vh * .12, y0 - vh * (.5 + Math.random() * .2)) - y0;
  if (calm || !el.animate) { el.style.transform = "translate(" + x0 + "px," + (y0 + ty) + "px) scale(.4)"; return; }
  const a = el.animate([
    { transform: "translate(" + x0 + "px," + y0 + "px) scale(.6)", opacity: 0 },
    { transform: "translate(" + x0 + "px," + (y0 - 20) + "px) scale(1)", opacity: 1, offset: .08 },
    { transform: "translate(" + (x0 + tx * .3 - 20) + "px," + (y0 + ty * .4) + "px) scale(.85) rotate(-4deg)", offset: .4 },
    { transform: "translate(" + (x0 + tx * .7 + 20) + "px," + (y0 + ty * .8) + "px) scale(.5) rotate(4deg)", offset: .8 },
    { transform: "translate(" + (x0 + tx) + "px," + (y0 + ty) + "px) scale(.22)", opacity: .9 }
  ], { duration: 6500, easing: "cubic-bezier(.25,.1,.35,1)", fill: "forwards" });
  a.onfinish = () => {
    const s = document.createElement("img"); s.className = "settled"; s.alt = ""; s.src = el.querySelector("img").src;
    s.style.left = (x0 + tx + 26) + "px"; s.style.top = (y0 + ty + 30) + "px";
    launch.appendChild(s); el.remove();
    const all = launch.querySelectorAll(".settled"); if (all.length > 40) all[0].remove();
  };
});

/* calendar: Apple devices open the .ics, others get Google Calendar */
/* rsvp */
let guests = 2;
$("g-minus").addEventListener("click", () => { guests = Math.max(1, guests - 1); $("g-count").textContent = guests; });
$("g-plus").addEventListener("click", () => { guests = Math.min(15, guests + 1); $("g-count").textContent = guests; });
const form = $("rsvp-form");
form.addEventListener("change", () => {
  $("att-yes").style.display = form.querySelector("input[name=att]:checked").value === "yes" ? "grid" : "none";
});


/* share */
function toast(t){ const el = $("toast"); el.textContent = t; el.hidden = false; clearTimeout(toast.t); toast.t = setTimeout(() => el.hidden = true, 2200); }
